contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Function drives a single Put then checks that the stored balance reflects the deposit.
    // Parameters:
    // - unlockTime: passed to Put
    // - deposit: amount of wei to send with Put
    // Precondition: this contract must hold at least `deposit` wei when calling this function.
    function runTest(uint unlockTime, uint deposit) public payable {
        require(address(this).balance >= deposit, "insufficient balance for test");
        // make the Put call that should succeed on the original contract but will revert on the mutant
        c.Put{value: deposit}(unlockTime);

        // Observe the stored balance for this contract's address via the public mapping getter Acc
        // The getter for Acc returns (unlockTime, balance) because Holder has two uints and mapping is public.
        (, uint storedBalance) = c.Acc(address(this));

        // Assert that the stored balance equals the deposited amount
        assert(storedBalance == deposit);
    }

    // Allow funding this test contract
    receive() external payable {}
}

