pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzzed params: actor and a candidate unlockTime that may be in the future
    function testFuzz_property(address actor, uint256 _unlockTime, uint256 value) public {
        // keep actor nonzero
        vm.assume(actor != address(0));
        // keep value small enough to fund and positive (allow zero as well)
        value = bound(value, 0, 5 ether);
        // fund the actor so they can send value
        vm.deal(actor, value + 1 ether);

        // ensure we test both cases where _unlockTime may be <= now or > now
        // call Put as the actor, sending `value` wei and candidate _unlockTime
        vm.prank(actor);
        if (value > 0) {
            // make a payable call
            (bool ok, ) = address(c).call{value: value}(abi.encodeWithSignature("Put(uint256)", _unlockTime));
            // Put is not expected to revert on valid inputs; still proceed
            // We won't assert on ok directly because both versions may return ok=true
        } else {
            // zero-value call
            (bool ok, ) = address(c).call(abi.encodeWithSignature("Put(uint256)", _unlockTime));
        }

        // single assertion: the stored unlockTime for actor is >= current block.timestamp
        // This must hold for the correct contract (it uses max(_unlockTime, now)).
        // The mutant that unconditionaly sets unlockTime = now still satisfies unlockTime >= now,
        // but the distinguishing intended rule is that if _unlockTime > now then stored unlockTime == _unlockTime.
        // We therefore assert the general rule that after Put the stored unlockTime is at least the minimum of _unlockTime and block.timestamp
        // which the correct contract actually ensures stored unlockTime >= block.timestamp and stored unlockTime >= min(_unlockTime, block.timestamp).
        // To make a single universal property that the correct contract always satisfies and the mutant breaks for some inputs,
        // we assert: stored unlockTime >= block.timestamp && (if _unlockTime > block.timestamp then stored unlockTime == _unlockTime)

        // Read stored unlockTime via public mapping getter Acc(address) returns (uint unlockTime, uint balance)
        (uint storedUnlockTime, ) = c.Acc(actor);

        // Now form the condition and assert it. This single assertTrue will pass on reference and fail on mutant for some fuzzed inputs
        bool cond = true;
        // always storedUnlockTime >= now
        cond = cond && (storedUnlockTime >= block.timestamp);
        // if caller requested a future unlockTime, the reference preserves it; the mutant loses it
        if (_unlockTime > block.timestamp) {
            cond = cond && (storedUnlockTime == _unlockTime);
        }

        assertTrue(cond);
    }
}

