import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzzed params: actor address, deposit amount, requested unlock time
    function testFuzz_property(address actor, uint256 amount, uint256 requestedUnlock) public {
        // keep actor non-zero and amount small enough to not overflow trivial sums
        vm.assume(actor != address(0));
        amount = bound(amount, 0, 10 ether);
        // ensure we can fund actor
        vm.deal(actor, amount);

        // Step 1: actor makes an initial Put with a large unlock time to set a high stored unlockTime
        uint256 largeUnlock = block.timestamp + 7 days + (requestedUnlock % 1000);
        vm.prank(actor);
        c.Put{value: amount}(largeUnlock);

        // read stored unlockTime after first deposit
        uint256 beforeUnlock = c.Acc(actor).unlockTime;

        // Step 2: actor calls Put again with the fuzzed requestedUnlock and possibly some value
        // (allow zero amount as well)
        uint256 useAmount = amount == 0 ? 0 : amount / 2;
        vm.deal(actor, useAmount);
        vm.prank(actor);
        c.Put{value: useAmount}(requestedUnlock);

        // read stored unlockTime after second deposit
        uint256 afterUnlock = c.Acc(actor).unlockTime;

        // The reference preserves a non-decreasing unlockTime: it sets unlockTime = max(previously set value or block.timestamp, provided _unlockTime)
        // Therefore afterUnlock must be >= beforeUnlock and also >= block.timestamp at the time of the second call.
        // We capture the current block.timestamp (same as used by contract) and assert the non-decreasing property.
        // Single assertion that should hold for the correct contract for all admissible inputs, but the mutant that unconditionally sets unlockTime = block.timestamp will make afterUnlock < beforeUnlock when requestedUnlock was large previously.
        assertTrue(afterUnlock >= beforeUnlock && afterUnlock >= block.timestamp);
    }
}

