pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // Fuzzed parameters: caller address, initialUnlock (to set up a larger existing unlockTime), putUnlock (the _unlockTime passed to Put), and amount to deposit
    function testFuzz_property(address actor, uint256 initialUnlock, uint256 putUnlock, uint256 amount) public {
        // keep actor non-zero
        vm.assume(actor != address(0));
        // bound amounts reasonably to avoid overflow in deals; allow zero too
        amount = bound(amount, 0, 10 ether);
        // ensure initialUnlock and putUnlock are within a wide range but bounded reasonably
        initialUnlock = bound(initialUnlock, block.timestamp, block.timestamp + 365 days);
        putUnlock = bound(putUnlock, block.timestamp, block.timestamp + 365 days);

        // 1) set up a prior larger unlockTime in storage by performing an initial Put with initialUnlock
        vm.deal(actor, amount + 1 ether); // give some balance to pay deposits
        vm.startPrank(actor);
        // first deposit to establish initial state
        c.Put{value: 1 ether}(initialUnlock);
        vm.stopPrank();

        // read previous unlockTime using public getter Acc(actor)
        (uint256 prevUnlockTime, uint256 prevBalance) = c.Acc(actor);

        // advance time a bit to simulate later call (but keep it before potential very large times)
        vm.warp(block.timestamp + 1);

        // 2) now call Put with putUnlock and deposit amount (may be zero)
        vm.deal(actor, amount);
        vm.startPrank(actor);
        bool ok;
        try c.Put{value: amount}(putUnlock) {
            ok = true;
        } catch {
            ok = false;
        }
        vm.stopPrank();

        // read resulting unlockTime
        (uint256 newUnlockTime, uint256 newBalance) = c.Acc(actor);

        // General invariant that the correct contract preserves: newUnlockTime >= prevUnlockTime && newUnlockTime >= the time of the Put call
        // We cannot directly read the exact timestamp when Put executed, but we know we warped to block.timestamp+1 before calling; at call time block.timestamp is >= prev warp value.
        // Compute a conservative lower bound for call-time now (it is at least the warp value we set earlier)
        uint256 callTimeLowerBound = block.timestamp;

        // SINGLE assertion: the contract must not have decreased the unlockTime below its previous stored value or below the call time lower bound.
        // This holds for the reference implementation for all inputs, but the mutant that sets unlockTime = block.timestamp can decrease a previously larger unlockTime.
        assertTrue(newUnlockTime >= prevUnlockTime && newUnlockTime >= callTimeLowerBound && ok);
    }
}

