    // fuzz: actor (address) and amount to deposit/withdraw and unlock time delta
    function testFuzz_property(address actor, uint256 depositAmt, uint256 withdrawAmt, uint256 unlockDelta) public {
        // keep wide but reasonable ranges
        vm.assume(actor != address(0));
        depositAmt = bound(depositAmt, 1 wei, 10 ether);
        withdrawAmt = bound(withdrawAmt, 1 wei, 10 ether);
        // ensure unlock time we set is in the future relative to block.timestamp by a bounded amount
        unlockDelta = bound(unlockDelta, 0, 10000);

        // prepare actor with funds
        vm.deal(actor, depositAmt + 1 ether);

        // actor deposits funds by calling fallback -> Put(0)
        vm.prank(actor);
        c.f{value: depositAmt}();

        // set the holder's unlockTime to past so Collect can proceed: we call Put with explicit unlock
        uint256 newUnlock = block.timestamp + unlockDelta;
        vm.prank(actor);
        c.Put{value: 0}(newUnlock);

        // if unlockDelta > 0, warp forward so block.timestamp > acc.unlockTime when collecting
        if (unlockDelta > 0) {
            vm.warp(newUnlock + 1);
        } else {
            // ensure time passes a bit
            vm.warp(block.timestamp + 1);
        }

        // read prior balance
        uint256 prior = c.Acc(actor).balance;

        // Only attempt collect if prior >= MinSum and prior >= withdrawAmt
        uint256 minSum = c.MinSum();
        vm.assume(prior >= minSum && prior >= withdrawAmt);

        // perform Collect as the actor and capture whether call succeeded
        bool ok;
        vm.prank(actor);
        try c.Collect(withdrawAmt) {
            ok = true;
        } catch {
            ok = false;
        }

        // After successful Collect, the invariant: stored balance == prior - withdrawAmt
        // We assert that property (single assert). This holds for the reference but can fail for the mutant
        if (ok) {
            uint256 after = c.Acc(actor).balance;
            assertTrue(after == prior - withdrawAmt);
        } else {
            // if Collect reverted, the reference still guarantees state unchanged: balance == prior
            uint256 after = c.Acc(actor).balance;
            assertTrue(after == prior);
        }
    }
}

